from pathlib import Path
s=Path('game.js').read_text()
# Strip strings/comments approximately to find brace balance and report first unmatched close/last open.
stack=[]
i=0
state='code'
quote=''
while i<len(s):
    c=s[i]
    n=s[i:i+2]
    if state=='code':
        if c in "'\"`": state='quote'; quote=c
        elif n=='//': state='line'; i+=1
        elif n=='/*': state='block'; i+=1
        elif c=='{': stack.append(i)
        elif c=='}':
            if stack: stack.pop()
            else: print('unexpected close at', i)
    elif state=='quote':
        if c=='\\': i+=1
        elif c==quote: state='code'
    elif state=='line':
        if c=='\n': state='code'
    elif state=='block':
        if n=='*/': state='code'; i+=1
    i+=1
print('remaining opens:',len(stack))
for i in stack[-10:]:
    print(i, s.count('\n',0,i)+1, s[max(0,i-80):i+100].replace('\n',' '))
