function firePlayerShot(angle,damage,velocity,life,extra={}){bullets.push({x:player.x,y:player.y,vx:Math.cos(angle)*velocity,vy:Math.sin(angle)*velocity,life,damage,color:player.light,owner:player,r:.15,...extra})}
function shoot(){if(mode!=='playing'||player.alive===false||player.attack>0||player.ammo<=0)return;let kit=player.kit||kits[0],angle=player.angle,target=targetFor(player);if(pointer.aiming&&pointer.dragAiming){angle=Math.atan2(pointer.dy/15-pointer.dx/31,pointer.dy/15+pointer.dx/31)}else if(pointer.down&&!pointer.aiming){let aim=unproject(pointer.x,pointer.y);angle=Math.atan2(aim.y-player.y,aim.x-player.x)}else if(target){angle=Math.atan2(target.y-player.y,target.x-player.x)}player.angle=angle;player.attack=kit.reload*.34;player.ammo--;player.reload=kit.reload;for(let i=0;i<kit.count;i++){let offset=(i-(kit.count-1)/2)*kit.spread;firePlayerShot(angle+offset,kit.damage,kit.velocity,kit.life,{pierce:kit.pierce||0,splash:kit.splash||0,lifesteal:kit.lifesteal||0})}updateAmmo()}
